export interface DatabasesLeaseLengthRequest {
  action: 'lease_length';
  database?: DatabaseSelector;
  /** Minimum 10000. Maximum 7776000000. */
  length_ms: number | null;
  name?: never;
  kind?: never;
  sharingMode?: never;
  link?: never;
  include_full?: never;
  include_definition_ids?: never;
  schema?: never;
  intent?: never;
  retention?: never;
  app_id?: never;
  grantee?: never;
  role?: never;
  mutation?: never;
  idempotency_key?: never;
  mutationId?: never;
}

/** POST /api/databases/{id}/share/link. Mint local open material from saved credentials and the home identity. Empty owner body. Does not call ExeMem blob/bytes or share members. No cloud account is 409 no_cloud_account. Still enrolling waits, then 503 enrolling with Retry-After. Saved credentials that cannot be verified is 503 busy. */
export interface DatabasesShareLinkRequest {
  action: 'share_link';
  database?: DatabaseSelector;
  name?: never;
  kind?: never;
  sharingMode?: never;
  link?: never;
  include_full?: never;
  include_definition_ids?: never;
  schema?: never;
  intent?: never;
  retention?: never;
  app_id?: never;
  grantee?: never;
  role?: never;
  length_ms?: never;
  mutation?: never;
  idempotency_key?: never;
  mutationId?: never;
}

/** POST /api/databases/{id}/submissions. idempotency_key becomes the Idempotency-Key header. The node signs the proposal on this member stream, appends it to the local log, and does not write a record. A folded role other than submit or write is 403 permission_denied and the message is "this member cannot submit this shared mutation", with no Retry-After. An append that is not confirmed is 503 busy, the message is "shared mutation was not confirmed", and Retry-After says when to retry. */
export interface DatabasesSubmitRequest {
  action: 'submit';
  database?: DatabaseSelector;
  mutation: DatabasesMutation;
  /** Non-nil lowercase UUID. */
  idempotency_key: string;
  name?: never;
  kind?: never;
  sharingMode?: never;
  link?: never;
  include_full?: never;
  include_definition_ids?: never;
  schema?: never;
  intent?: never;
  retention?: never;
  app_id?: never;
  grantee?: never;
  role?: never;
  length_ms?: never;
  mutationId?: never;
}

/** POST /api/databases/{id}/change. One change to one record of the database, with the same document and the same idempotency_key rules as submit. The node decides. When this node may sign a direct entry now (an owned or personal database, or a received database whose role is write and whose newest lease covers it), the change is applied at once and the reply is 200 with status applied. Otherwise the node queues a proposal and the reply is 202 with status pending and submission_sequence. A member that may neither write nor propose is 403. A file in the document is 400. The direct path has no repeat protection by id: a repeat of an applied create or replace is refused 409 by its condition. */
export interface DatabasesChangeRequest {
  action: 'change';
  database?: DatabaseSelector;
  mutation: DatabasesMutation;
  /** Non-nil lowercase UUID. */
  idempotency_key: string;
  name?: never;
  kind?: never;
  sharingMode?: never;
  link?: never;
  include_full?: never;
  include_definition_ids?: never;
  schema?: never;
  intent?: never;
  retention?: never;
  app_id?: never;
  grantee?: never;
  role?: never;
  length_ms?: never;
  mutationId?: never;
}

export interface DatabasesStatusRequest {
  action: 'submission_status';
  database?: DatabaseSelector;
  mutationId: string;
  name?: never;
  kind?: never;
  sharingMode?: never;
  link?: never;
  include_full?: never;
  include_definition_ids?: never;
  schema?: never;
  intent?: never;
  retention?: never;
  app_id?: never;
  grantee?: never;
  role?: never;
  length_ms?: never;
  mutation?: never;
  idempotency_key?: never;
}

/** One action. A field from another action is invalid_request. */
export type DatabasesRequest = DatabasesListRequest | DatabasesCreateRequest | DatabasesAcceptLinkRequest | DatabasesSchemasRequest | DatabasesDeclareRequest | DatabasesGrantRequest | DatabasesRevokeRequest | DatabasesGrantsRequest | DatabasesHeadsRequest | DatabasesRelaysRequest | DatabasesBootstrapRelayRequest | DatabasesLeaseRequest | DatabasesLeaseLengthRequest | DatabasesShareLinkRequest | DatabasesSubmitRequest | DatabasesChangeRequest | DatabasesStatusRequest;

/** The newest write lease held in this database's signed history. covers says whether the lease names this node. directWrites says whether this node signs direct entries now (role is write and now is before directWritesUntilMs). */
export interface DatabasesLease {
  /** 64 lowercase hex characters. */
  entryHash: string;
  /** Integer. Minimum 0. */
  authoredAtMs: number;
  /** Integer. Minimum 0. */
  expiresAtMs: number;
  /** Integer. Minimum 0. */
  closesAtMs: number;
  covers: boolean;
  directWrites: boolean;
  /** Minimum 0. */
  directWritesUntilMs: number | null;
}

/** Folded access of this node on a received signed-log database. Omitted when no history is held or the key has no active grant. */
export interface DatabasesSelfAccess {
  role: 'read' | 'submit' | 'write';
  lease?: DatabasesLease;
}

/** The last relay upload attempt for one received database. It is kept in memory and is absent again after a restart. at is RFC 3339 UTC with second precision. outcome is confirmed when the relay accepted the append batch, refused on HTTP 401 or 403, or unconfirmed otherwise. status is the HTTP status when the relay answered, no_credentials when the node had no usable cloud credentials, or null when the attempt failed before a status. */
export interface DatabasesPublishAttempt {
  at: string;
  outcome: 'confirmed' | 'refused' | 'unconfirmed';
  status: number | string | null;
}

/** How many signed log entries of this member are past the upload cursor, and the last relay append attempt. pending is null until a path in this process reads the log. Owned databases omit this object. */
export interface DatabasesPublish {
  /** Signed log entries past uploaded.json. Null until this process has read the log, including after a restart. Zero when the registration is not a signed log. */
  pending: null | number;
  /** Null until a publish attempt, and null again after a restart. */
  lastAttempt: null | DatabasesPublishAttempt;
}

/** One database from list, create, or accept. A received database includes publish, and includes selfAccess when this node holds its signed history and has an active role. An owned shareable database includes leaseLengthMs when a lease length is set. */
export interface DatabasesListItem {
  /** Integer. Minimum 10000. */
  leaseLengthMs?: number;
  selfAccess?: DatabasesSelfAccess;
  publish?: DatabasesPublish;
  [key: string]: unknown;
}

export interface DatabasesListReply {
  ok: boolean;
  user_hash: string;
  databases: DatabasesListItem[];
  [key: string]: unknown;
}

/** create and accept. database is the owner row. */
export interface DatabasesDatabaseReply {
  ok: boolean;
  user_hash: string;
  database: DatabasesListItem;
  [key: string]: unknown;
}

export interface DatabasesSchemasReply {
  ok: boolean;
  user_hash: string;
  schemas: { [key: string]: unknown }[];
  /** Integer. Minimum 0. */
  count: number;
  [key: string]: unknown;
}

/** The owner declare-schema envelope. */
export interface DatabasesDeclareReply {
  ok: boolean;
  user_hash: string;
  schema_name: string;
  definition_id: string;
  resolution: 'register' | 'reuse';
  [key: string]: unknown;
}

/** grant and revoke. role is revoked after a revoke. entryHash and writerSeq name the signed entry on this node's publisher stream. */
export interface DatabasesGrantReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  /** 64 lowercase hex characters. */
  entryHash: string;
  /** Integer. Minimum 1. */
  writerSeq: number;
  role: 'read' | 'submit' | 'write' | 'revoked';
  [key: string]: unknown;
}

export interface DatabasesGrantMember {
  /** 64 lowercase hex characters. */
  nodeKey: string;
  role: 'read' | 'submit' | 'write' | 'revoked';
}

/** The folded grants. Explicitly revoked members appear with role revoked; never-granted keys are absent. any is present only for public read. entryHash and writerSeq name the latest signed grant. */
export interface DatabasesGrantsReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  members: DatabasesGrantMember[];
  any?: 'read';
  entryHash?: string;
  /** Integer. Minimum 1. */
  writerSeq?: number;
  [key: string]: unknown;
}

export interface DatabasesHead {
  deviceId: string;
  /** Integer. Minimum 1. */
  writerSeq: number;
  entryHash: string;
}

export interface DatabasesHeadsReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  heads: DatabasesHead[];
  [key: string]: unknown;
}

export interface DatabasesRelaysReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  urls: string[];
  [key: string]: unknown;
}

export interface DatabasesBootstrapRelayReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  url: string;
  [key: string]: unknown;
}

/** The lease view of an owned or received database. leaseLengthMs is present on an owned database that configured one. */
export interface DatabasesLeaseReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  role: null | 'read' | 'submit' | 'write';
  /** Integer. Minimum 10000. */
  leaseLengthMs?: number;
  lease: null | DatabasesLease;
  [key: string]: unknown;
}

/** The updated lease length of an owned shareable database, or null when cleared. */
export interface DatabasesLeaseLengthReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  /** Minimum 10000. */
  leaseLengthMs: number | null;
  [key: string]: unknown;
}

/** The owner open-material envelope. link is one opaque token People can wrap as a consent code, not a URL. */
export interface DatabasesShareLinkReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  link: string;
  [key: string]: unknown;
}

export interface DatabasesSubmitReply {
  ok: true;
  status: 'submitted';
  mutation_id: string;
  /** Integer. Minimum 1. */
  submission_sequence: number;
  [key: string]: unknown;
}

/** applied is 200. pending is 202 and carries submission_sequence. */
export interface DatabasesChangeReply {
  ok: true;
  status: 'applied' | 'pending';
  mutation_id: string;
  /** Integer. Minimum 1. */
  submission_sequence?: number;
  [key: string]: unknown;
}

export interface DatabasesStatusReply {
  ok: true;
  mutation_id: string;
  status: string;
  [key: string]: unknown;
}

/** Success JSON for an action other than submit. submit answers 202. change answers 200 applied or 202 pending. */
export type DatabasesReply = DatabasesListReply | DatabasesDatabaseReply | DatabasesSchemasReply | DatabasesDeclareReply | DatabasesGrantReply | DatabasesGrantsReply | DatabasesHeadsReply | DatabasesRelaysReply | DatabasesBootstrapRelayReply | DatabasesLeaseReply | DatabasesLeaseLengthReply | DatabasesShareLinkReply | DatabasesChangeReply | DatabasesStatusReply;

/** Maximum items 256. */
export type ManifestNameList = string[];

/** Every schema on the node. It names none of them. A listing may carry it at every app API version. */
export type AllSchemas = '*';

/** Schema names the app asks for, or * for every schema. */
export type ManifestSchemaSide = AllSchemas | ManifestNameList;

/** The access block a developer writes in the app manifest. Publish reads read, write, and extensions and ignores any other key. read and write are each a list of schema names or the string *. A schema name is 1 to 128 characters of ASCII letters, digits, underscore, dot, slash, or hyphen. An extension name is 1 to 40 characters of lowercase ASCII letters, digits, or underscore. A name that breaks those rules fails publish with one generic message. The schema entry itself is not defined here. */
export interface ManifestAccess {
  /** Schemas the app reads. * means every schema and names none. */
  read: ManifestSchemaSide;
  /** Schemas the app writes. * means every schema and names none. It does not grant read. */
  write: ManifestSchemaSide;
  /** Extension names the app calls. The list is not limited to changes and databases. Install refuses a name this build cannot grant. This build grants changes and databases. * is not a value here. */
  extensions: ManifestNameList;
  [key: string]: unknown;
}

/** Schema name to the definition id of the one version the app was built against. At most 256 entries. A name is 1 to 128 characters of ASCII letters, digits, underscore, dot, slash, or hyphen. A definition id is 64 lowercase hex characters. */
export interface DefinitionMap {
  [key: string]: string;
}

/** Schema name to definition id, or * for every schema. */
export type ListingSchemaSide = AllSchemas | DefinitionMap;

/** The access block on the signed listing. Publish replaces each schema name with that name and its definition id. The string * stays * and means every schema. * is allowed at every app API version. Unknown keys are rejected. */
export interface ListingAccess {
  /** Schemas the app reads, or * for every schema. */
  read: ListingSchemaSide;
  /** Schemas the app writes, or * for every schema. */
  write: ListingSchemaSide;
  /** Extension names. An extension name is 1 to 40 characters of lowercase ASCII letters, digits, or underscore. Unknown names fail install. This build grants changes and databases. Maximum items 256. */
  extensions: string[];
}
